mkdir -p /tmp/probe && cat > /tmp/probe/Probe.java <<'EOF'
import org.jsoup.Jsoup;
import org.jsoup.nodes.Document;

public class Probe {
    static void check(String name, Object actual, Object expected) {
        boolean ok = expected.equals(actual);
        System.out.println((ok ? "PASS " : "FAIL ") + name);
        if (!ok) {
            System.out.println("  expected: " + expected);
            System.out.println("  actual:   " + actual);
        }
    }
    public static void main(String[] a) {
        // 1. RCDATA: start tags, attrs, stray < are text
        Document d = Jsoup.parse("<title><b>bold</b> <i attr='x'> and < broken</title><p>after</p>");
        check("title text", d.title(), "<b>bold</b> <i attr='x'> and < broken");
        check("title children", d.head().select("title").first().childNodeSize(), 1);
        check("sibling after", d.body().select("p").size() + d.head().select("p").size(), 1);

        // case-insensitive end tag
        d = Jsoup.parse("<title>one</TITLE><p>two</p>");
        check("case-insensitive end", d.title(), "one");

        // textarea
        d = Jsoup.parse("<textarea><div>x</div> &amp; < broken</textarea><span>after</span>");
        String ta = d.select("textarea").first().text();
        check("textarea text", ta, "<div>x</div> & < broken");
        check("textarea sibling", d.select("span").size(), 1);

        // 2. numeric char refs in RCDATA
        d = Jsoup.parse("<title>A&#66;C &#x44; &#X45; &#70 semi &#x48;semi</title>");
        check("decimal+hex refs", d.title(), "ABC DE Fsemi Hsemi");

        // invalid numeric ref -> replacement char, doesn't swallow
        d = Jsoup.parse("<title>&#xD800;x &#0;y &#x110000;z</title>");
        check("invalid refs", d.title(), "�x �y �z");

        // consecutive valid/invalid
        d = Jsoup.parse("<title>&#65;&#0;&#66;</title>");
        check("consecutive", d.title(), "A�B");

        // invalid fragments preserved literally
        d = Jsoup.parse("<title>&# &#x &#zz &notreal;</title>");
        check("invalid literal", d.title(), "&# &#x &#zz &notreal;");

        // 3. textarea newlines/entities round-trip
        String taHtml = "<textarea>line1\nline2 &amp; <b>not bold</b></textarea>";
        d = Jsoup.parse(taHtml);
        String t1 = d.select("textarea").first().text();
        Document d2 = Jsoup.parse(d.html());
        String t2 = d2.select("textarea").first().text();
        check("textarea reparse stable", t2, t1);

        // 4. script/style rawtext
        d = Jsoup.parse("<script type='text/javascript'>if (a &lt; b) { x = '&#65;'; }</script>");
        check("script raw", d.select("script").first().html(), "if (a &lt; b) { x = '&#65;'; }");
        d = Jsoup.parse("<SCRIPT>var x = '&amp;';</SCRIPT>");
        check("script case", d.select("script").first().html(), "var x = '&amp;';");
        d = Jsoup.parse("<style>a > b { content: '&#66;'; }</style>");
        check("style raw", d.select("style").first().html(), "a > b { content: '&#66;'; }");

        // 5. missing end tag -> text to EOF, no exception
        d = Jsoup.parse("<title>never closed <b>x</b>");
        check("unclosed title", d.title(), "never closed <b>x</b>");

        // 6. serialize-reparse stability for title
        d = Jsoup.parse("<title>T &amp; &#65; <b></title><p>sib</p>");
        d2 = Jsoup.parse(d.html());
        check("title reparse", d2.title(), d.title());
        check("sib preserved", d2.select("p").size(), 1);
    }
}
EOF
