import org.jsoup.Jsoup;
import org.jsoup.nodes.Document;

public class Probe2 {
    static int fails = 0;
    static void check(String name, Object actual, Object expected) {
        boolean ok = expected.equals(actual);
        System.out.println((ok ? "PASS " : "FAIL ") + name);
        if (!ok) { fails++;
            System.out.println("  expected: " + esc(expected));
            System.out.println("  actual:   " + esc(actual));
        }
    }
    static String esc(Object o) { return o.toString().replace("\n","\\n").replace("\r","\\r"); }
    public static void main(String[] a) {
        // RCDATA basics
        Document d = Jsoup.parse("<title><b>bold</b> <i attr='x'> and < broken</title><p>after</p>");
        check("title rcdata text", d.title(), "<b>bold</b> <i attr='x'> and < broken");
        check("title no children", d.head().select("title").first().childNodeSize(), 1);
        check("sibling order", d.body().select("p").first().text(), "after");

        d = Jsoup.parse("<title>one</TITLE><p>two</p>");
        check("case-insensitive end tag", d.title(), "one");

        // numeric refs in RCDATA
        d = Jsoup.parse("<title>A&#66;C&#x44;&#X45;F&#71</title>");
        check("dec/hex/x/X/no-semi", d.title(), "ABCDEFG");
        d = Jsoup.parse("<title>&#0;x&#xD800;y&#x110000;z&#65;&#0;&#66;</title>");
        check("invalid -> FFFD, no swallow", d.title(), "�x�y�zA�B");
        d = Jsoup.parse("<title>&# &#x &#zz</title>");
        check("invalid fragments literal", d.title(), "&# &#x &#zz");

        // textarea: newline, entities, angle brackets, nested-looking tags
        d = Jsoup.parse("<textarea>line1\nline2 &amp; <b>not bold</b> < broken</textarea><span>s</span>");
        String t = d.select("textarea").first().text();
        check("textarea text", t, "line1\nline2 & <b>not bold</b> < broken");
        check("textarea reparse", Jsoup.parse(d.html()).select("textarea").first().text(), t);
        check("textarea sibling", d.select("span").first().text(), "s");

        // textarea initial newline ignored, but preserved through serialize+reparse
        d = Jsoup.parse("<textarea>\nA</textarea>");
        check("textarea initial LF consumed", d.select("textarea").first().text(), "A");
        check("textarea roundtrip", Jsoup.parse(d.outerHtml()).select("textarea").first().text(), "A");
        d = Jsoup.parse("<textarea>\n\nA</textarea>");
        check("textarea double LF", Jsoup.parse(d.outerHtml()).select("textarea").first().text(), "\nA");

        // title text stability
        d = Jsoup.parse("<title>T &amp; &#65; <b></title><p>sib</p>");
        check("title reparse stable", Jsoup.parse(d.html()).title(), d.title());

        // script/style rawtext: refs and entities NOT decoded
        d = Jsoup.parse("<script type='text/javascript'>var s='&#65;&amp;<b>';</script>");
        check("script raw", d.select("script").first().html(), "var s='&#65;&amp;<b>';");
        d = Jsoup.parse("<STYLE>a>b{content:'&#66;'}</STYLE>");
        check("style raw case", d.select("style").first().html(), "a>b{content:'&#66;'}");
        d = Jsoup.parse("<script data-x='&amp;'>if(a<b&&c>d)&#71;</script><p>after</p>");
        check("script raw with attrs", d.select("script").first().html(), "if(a<b&&c>d)&#71;");
        check("after script", d.select("p").first().text(), "after");

        // missing end tag -> text to EOF, no exception
        d = Jsoup.parse("<title>never closed <b>x</b>");
        check("unclosed title", d.title(), "never closed <b>x</b>");
        d = Jsoup.parse("<textarea>open <i>forever");
        check("unclosed textarea", d.select("textarea").first().text(), "open <i>forever");

        // elements/attrs after RCDATA keep order
        d = Jsoup.parse("<title>t</title><div a='1' b='2'>x</div><span>y</span>");
        check("attrs after", d.select("div").first().attributes().size(), 2);
        check("order after", d.body().children().eachTag().toString(), "[div, span]");

        // repeated parse stability
        String html = "<title>A &amp; &#66; <x></title><textarea>\nT&lt;</textarea><script>&#67;</script>";
        Document d1 = Jsoup.parse(html);
        Document d2 = Jsoup.parse(d1.html());
        Document d3 = Jsoup.parse(d2.html());
        check("parse/serialize idempotent", d3.html(), d2.html());
        check("title stable", d3.title(), "A & B <x>");
        check("textarea stable", d3.select("textarea").first().text(), "T<");
        check("script stable", d3.select("script").first().html(), "&#67;");

        System.out.println(fails == 0 ? "ALL PASS" : fails + " FAILURES");
    }
}
